

GLOBAL_CSS = '\n<style>\n  :root {\n    --ostin-navy:#1F2A44; --ostin-blue:#EAF2FA; --ostin-header:#F3F6FA;\n    --ostin-total:#DDEAF6; --ostin-border:#D8E0E8; --orders:#4A78C2;\n    --revenue:#4B9B67; --stock:#2D8C8C; --events:#C48A32;\n  }\n  .block-container {padding-top:1.05rem;padding-bottom:4rem;max-width:1760px;}\n  h1 {color:var(--ostin-navy);margin-bottom:.1rem;} h2,h3 {color:var(--ostin-navy);margin-top:1.2rem;}\n  .week-status {padding:11px 14px;border-radius:10px;margin:.35rem 0 .9rem 0;background:var(--ostin-blue);color:var(--ostin-navy);border:1px solid #D5E4F1;font-weight:600;}\n  .status-open {border-left:5px solid #4A78C2;} .status-closed {border-left:5px solid #4B9B67;}\n  .kpi-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.65rem;margin:.35rem 0 .9rem 0;}\n  .kpi-card {background:#fff;border:1px solid var(--ostin-border);border-top:4px solid #AAB4C3;border-radius:12px;padding:12px 14px;min-height:86px;box-shadow:0 1px 4px rgba(31,42,68,.05);}\n  .kpi-card.orders {border-top-color:var(--orders);background:linear-gradient(180deg,#F7FAFF,#FFF 55%);}\n  .kpi-card.revenue {border-top-color:var(--revenue);background:linear-gradient(180deg,#F5FBF7,#FFF 55%);}\n  .kpi-card.stock {border-top-color:var(--stock);background:linear-gradient(180deg,#F3FBFB,#FFF 55%);}\n  .kpi-card.events {border-top-color:var(--events);background:linear-gradient(180deg,#FFF9EF,#FFF 55%);}\n  .kpi-label {font-size:.82rem;color:#657086;margin-bottom:.28rem;} .kpi-value {font-size:1.55rem;font-weight:700;color:var(--ostin-navy);line-height:1.15;}\n  .section-note {font-size:.90rem;color:#677386;margin-top:-.35rem;margin-bottom:.6rem;}\n  .proxy-legend {display:flex;flex-wrap:wrap;gap:.45rem 1rem;padding:.58rem .8rem;margin-bottom:.55rem;border-radius:9px;background:#FAFBFD;border:1px solid #E1E6EC;font-size:.87rem;color:#485468;}\n  .proxy1 {background:#FFF3C4;padding:2px 6px;border-radius:4px;} .proxy2 {background:#FFE1C2;padding:2px 6px;border-radius:4px;}\n  .movement-legend {display:flex;flex-wrap:wrap;gap:.45rem .9rem;align-items:center;margin:.35rem 0 .75rem 0;font-size:.84rem;color:#536174;}\n  .legend-chip {padding:3px 7px;border-radius:5px;border:1px solid rgba(31,42,68,.06);}\n  .legend-positive {background:#DFF2E5;} .legend-negative {background:#F8DCDC;} .legend-neutral-up {background:#E3F0FA;} .legend-neutral-down {background:#FCEBCF;}\n  .ai-panel {background:linear-gradient(180deg,#F7FAFD 0%,#EEF5FB 100%);border:1px solid #D5E4F1;border-radius:14px;padding:14px 16px;margin-top:.4rem;}\n  .ai-on {color:#2F7D4A;font-weight:600;} .ai-off {color:#7B8490;font-weight:600;}\n  div[data-testid="stDataFrame"] {border:1px solid #E1E7ED;border-radius:8px;overflow:hidden;}\n  @media (max-width:900px) {.kpi-grid {grid-template-columns:repeat(2,minmax(0,1fr));}}\n  @media (max-width:560px) {.kpi-grid {grid-template-columns:1fr;}}\n</style>\n'
